// <auto-generated/>

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Chronos.Core.Commands;
using ZES.Infrastructure;
using ZES.Infrastructure.Domain;
using ZES.Infrastructure.Utils;
using ZES.Interfaces.Branching;
using ZES.Interfaces.Clocks;
using ZES.Interfaces.Domain;
using ZES.Interfaces.Infrastructure;
using IClock = ZES.Interfaces.Clocks.IClock;

namespace Chronos.Core.Queries
{
  [Transient]
  public class AssetQuoteHandler(
    IProjectionManager manager,
    IActiveTimeline activeTimeline,
    ILog log,
    IBranchManager branchManager,
    IClock clock,
    IQueryHandler<AssetPairInfoQuery, AssetPairInfo> pairInfoHandler,
    IQueryHandler<SingleAssetQuoteQuery, SingleAssetQuote> handler,
    ICommandHandler<UpdateQuote> updateQuoteHandler)
    : QueryHandlerBase<AssetQuoteQuery, AssetQuote, AssetPairsInfo>(manager, activeTimeline)
  {
    protected override async Task<AssetQuote> Handle(IProjectionState<AssetPairsInfo> projection, AssetQuoteQuery query)
    {
      var state = projection.State;
      state.Tree.Log = log;
      
      var timestamps = query.AdditionalTimestamps?.ToList();
      var quote = await Handle(state, query);
      if (query.AdditionalTimestamps == null)
        return quote;

      if (TryGetOverride(query, query.ForAsset, query.DomAsset, out _))
      {
        log.Warn("Asset quote overrides were provided for multiple timestamps query, is this expected?");
        return quote;
      }

      var timestamp = query.Timestamp;
      try
      {
        foreach (var t in query.AdditionalTimestamps ?? [])
        {
          query.Timestamp = t;
          query.AdditionalTimestamps = null;
          quote.HistoricalResults[t] = await Handle(state, query);
        }
      }
      finally
      {
        query.AdditionalTimestamps = timestamps;
        query.Timestamp = timestamp;
      }
      
      return quote;
    }

    public override async Task<AssetQuote> Handle<TState>(TState state, AssetQuoteQuery query)
    {
      if (state is not AssetPairsInfo info)
        throw new ArgumentException($"{nameof(AssetPairsInfo)} expected", nameof(state));
      
      var price = 1.0;
      var fordom = AssetPair.Fordom(query.ForAsset, query.DomAsset);
      var timestamp = query.Timestamp;
      if (query.Timeline != "")
        timestamp = branchManager.GetTime(query.Timeline);
      else if (timestamp == null)
        timestamp = branchManager.GetTime(branchManager.ActiveBranch);
    
      if(TryGetOverride(query, query.ForAsset, query.DomAsset, out var priceOverride))
        return new AssetQuote(new Quantity(priceOverride, query.DomAsset), timestamp.ToInstant());
      
      if (info.Pairs.ToList().Contains(fordom))
      {
        var result = await GetSingleAssetQuote(query, timestamp, query.ForAsset, query.DomAsset);
        price = result.Price;
      }
      else 
      {
        // try to triangulate the price
        var path = info.Tree.GetPath(query.ForAsset, query.DomAsset);
        if (path == null)
          throw new InvalidOperationException($"No path found from {query.ForAsset?.AssetId} to {query.DomAsset?.AssetId}");

        foreach (var (forAsset, domAsset) in path)
        {
          var isInverse = info.Pairs.Contains(AssetPair.Fordom(domAsset, forAsset));
          
          var pathResult = isInverse ? 
            await GetSingleAssetQuote(query, timestamp, domAsset, forAsset) 
            : await GetSingleAssetQuote(query, timestamp, forAsset, domAsset);
          
          var pathPrice = pathResult.Price;

          if (isInverse && pathPrice != 0.0)
            pathPrice = 1.0 / pathPrice;
          
          price *= pathPrice;
        }
      }
      
      return new AssetQuote(new Quantity(price, query.DomAsset), timestamp.ToInstant()); 
    }

    private static bool TryGetOverride(AssetQuoteQuery query, Asset forAsset, Asset domAsset, out double price)
    {
      price = 0.0;

      var fordom = AssetPair.Fordom(forAsset, domAsset);
      var direct = query.AssetQuoteOverrides?.SingleOrDefault(o =>
        string.Equals(o.SourceOperationId, query.SourceOperationId, StringComparison.OrdinalIgnoreCase) &&
        string.Equals(o.Fordom, fordom, StringComparison.OrdinalIgnoreCase));

      if (direct != null)
      {
        price = direct.Price;
        return true;
      }

      var inverseFordom = AssetPair.Fordom(domAsset, forAsset);
      var inverse = query.AssetQuoteOverrides?.SingleOrDefault(o =>
        string.Equals(o.SourceOperationId, query.SourceOperationId, StringComparison.OrdinalIgnoreCase) &&
        string.Equals(o.Fordom, inverseFordom, StringComparison.OrdinalIgnoreCase));

      if (inverse == null || inverse.Price == 0.0)
        return false;

      price = 1.0 / inverse.Price;
      return true;
    }

    private async Task<SingleAssetQuote> GetSingleAssetQuote(AssetQuoteQuery query, Time timestamp, Asset forAsset, Asset domAsset)
    {
      if (TryGetUnitConversionQuote(forAsset, domAsset, timestamp, out var quote))
        return quote;
      
      var key = (forAsset, domAsset, timestamp);

      query.SingleAssetQuotes ??= new Dictionary<(Asset asset, Asset denominator, Time timestamp), SingleAssetQuote>();
      if (query.SingleAssetQuotes.TryGetValue(key, out var cached))
        return cached;

      var quotes = await GetQuotes(query, timestamp, forAsset, domAsset);
      if (quotes != null)
      {
        query.SingleAssetQuotes[key] = quotes;
        foreach(var (t, historicalQuote) in quotes.HistoricalResults ?? [])
          query.SingleAssetQuotes[(forAsset, domAsset, t)] = historicalQuote;
      }

      return quotes;
    }

    private static bool TryGetUnitConversionQuote(Asset forAsset, Asset domAsset, Time timestamp, out SingleAssetQuote quote)
    {
      switch (forAsset.AssetId)
      {
        case "GBP" when domAsset.AssetId == "GBX":
          quote = new SingleAssetQuote(100.0, timestamp.ToInstant());
          return true;
        case "GBX" when domAsset.AssetId == "GBP":
          quote = new SingleAssetQuote(0.01, timestamp.ToInstant());
          return true;
        default:
          quote = null;
          return false;
      }
    }
    
    private async Task<SingleAssetQuote> GetQuotes(AssetQuoteQuery query, Time timestamp, Asset forAsset, Asset domAsset)
    {
      var now = clock.GetCurrentInstant();
      var intraday =  timestamp.Date() == now.Date();

      if(TryGetOverride(query, forAsset, domAsset, out var price))
        return new SingleAssetQuote(price, timestamp.ToInstant());
      
      var assetPairInfo = await pairInfoHandler.Handle(new AssetPairInfoQuery(AssetPair.Fordom(forAsset, domAsset)));
      if (assetPairInfo == null)
        throw new InvalidOperationException($"No asset pair info found for {forAsset}{domAsset}");
      var useStaleQuotes = assetPairInfo.UseStaleQuotes;
      
      var fordom = AssetPair.Fordom(forAsset, domAsset);
      if (query.UpdateQuote && (!useStaleQuotes || assetPairInfo.QuoteDates.Length == 0))
        await UpdateQuotes(assetPairInfo, timestamp, query.AdditionalTimestamps, query.EnforceCache, query.UseBatching);

      var result = await handler.Handle(new SingleAssetQuoteQuery(fordom)
      {
        Timeline = query.Timeline,
        Timestamp = timestamp,
        AdditionalTimestamps = query.AdditionalTimestamps,
      });

      if (result == null)
      {
        log.Error($"No pricing data found for {fordom}");
        return new SingleAssetQuote(double.NaN, timestamp.ToInstant());
      }

      var historicalResults = result.HistoricalResults;
      var invalidResults = historicalResults.Where(r => r.Value == null || double.IsNaN(r.Value.Price)).Select(x => x.Key).ToList();
      if(double.IsNaN(result.Price))
        invalidResults.Add(timestamp);
      
      if(useStaleQuotes && invalidResults.Count == 0)
        return result;

      invalidResults = historicalResults.Where(r => r.Value == null || !r.Value.IsValid(r.Key.ToInstant())).Select(x => x.Key).ToList();
      if(!result.IsValid(timestamp.ToInstant(), intraday))
        invalidResults.Add(timestamp);

      if (invalidResults.Count == 0)
        return result;

      var eodTimestamps = invalidResults.Select(t => t.ToInstant().EndOfDay().ToTime()).Distinct().OrderBy(x => x).ToList();
      var eodTimestamp = eodTimestamps[^1];
      var eodResult = await handler.Handle(new SingleAssetQuoteQuery(fordom)
      {
        Timeline = query.Timeline,
        Timestamp = eodTimestamp,
        AdditionalTimestamps = eodTimestamps.Take(eodTimestamps.Count - 1).ToList()
      });
      foreach (var t in invalidResults.ToList())
      {
        var fallbackTimestamp = t.ToInstant().EndOfDay().ToTime();
        var r = fallbackTimestamp == eodTimestamp
          ? eodResult
          : eodResult.HistoricalResults.GetValueOrDefault(fallbackTimestamp);
       
        if (r == null || !r.IsValid(t.ToInstant()))
          continue;

        if (t == timestamp)
          result = r;
        else
          historicalResults[t] = r;
        
        invalidResults.Remove(t);
      }
      
      if (invalidResults.Count == 0)
        return new SingleAssetQuote(result.Price, timestamp.ToInstant()) { HistoricalResults = historicalResults }; 
     
      log.Warn($"Stale pricing data found for {fordom} : {string.Join(", ", invalidResults)}");      
      foreach (var t in invalidResults)
        historicalResults[t] = new SingleAssetQuote(0.0, t.ToInstant()); 
      return new SingleAssetQuote(result.IsValid(timestamp.ToInstant(), intraday) ? result.Price : 0.0, timestamp.ToInstant()) { HistoricalResults = historicalResults };
    }   
    
    private async Task UpdateQuotes(AssetPairInfo assetPairInfo, Time timestamp, IEnumerable<Time> additionalTimestamps, bool enforceCache, bool useBatching)
    {
      var fordom = AssetPair.Fordom(assetPairInfo.ForAsset, assetPairInfo.DomAsset);
      
      var now = clock.GetCurrentInstant();
      var intraday = timestamp.Date() == now.Date();
    
      var quoteDates = assetPairInfo?.QuoteDates?.ToHashSet() ?? [];
      var holidayCalendar = assetPairInfo?.HolidayCalendar;
      var supportsIntraday = assetPairInfo.SupportsIntraday;

      var effectiveQuoteDates = quoteDates?
        .GroupBy(d => d.RollToWorkingDay(holidayCalendar : holidayCalendar).Date())
        .ToDictionary(g => g.Key, g => g.ToList()) ?? [];

      var needsUpdate = !QuoteExtensions.HasExistingQuote(timestamp.ToInstant(), quoteDates, effectiveQuoteDates, intraday,supportsIntraday, holidayCalendar);
      var timestamps = additionalTimestamps?.Where(t => 
        !QuoteExtensions.HasExistingQuote(t.ToInstant(), quoteDates, effectiveQuoteDates, false, supportsIntraday, holidayCalendar)).ToList();

      if (!needsUpdate && timestamps is { Count: > 0 })
      {
        timestamp = timestamps.Max();
        timestamps = timestamps.Where(t => t != timestamp).OrderBy(t => t).ToList();
        needsUpdate = true;
      }

      // we always try to update quote for intraday if requested
      if (needsUpdate)
        await updateQuoteHandler.Handle(new UpdateQuote(fordom) { Ephemeral = true, EnforceCache = enforceCache, Timestamp = timestamp, AdditionalTimestamps = timestamps, StoreInLog = false, UseBatching = useBatching } );
    }
  }
}

